(x, y, t) => {
  const cx = 240, cy = 120;
  let wx = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  let wy = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  wx += Math.sin((x+y)*0.01+t*0.5)*8 + Math.cos((x-y)*0.012-t*0.4)*6;
  wy += Math.cos((x-y)*0.01-t*0.45)*8 + Math.sin((x+y)*0.013+t*0.55)*6;
  let sx = x+wx, sy = y+wy;
  const wx2 = Math.sin(sx*0.025+t*0.7)*5 + Math.cos(sy*0.03-t*0.6)*4;
  const wy2 = Math.cos(sy*0.025-t*0.65)*5 + Math.sin(sx*0.028+t*0.75)*4;
  sx += wx2; sy += wy2;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0.7],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.6],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 0.8],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 0.75],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.65],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+2)*50, 0.14, 1.3, 0.55],
    [400+Math.cos(t*0.55+1)*60, 200+Math.sin(t*0.75+4)*40, 0.11, 1.8, 0.7]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp)*w;
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    cS += Math.sin(d*f*1.3-t*sp*0.4+3.0)*w*0.5;
  }
  const tw = 5.35;
  aS/=tw; iS/=tw; cS/=tw;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2
    + Math.sin(sx*0.08+t*1.5)*Math.cos(sy*0.06-t*1.2)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    + Math.sin(dist*0.07-ang*5+t*0.8)*0.2;
  const micro = (Math.sin(sx*0.3+t*3)*Math.sin(sy*0.3-t*2.5)+Math.sin(sx*0.25-sy*0.25+t*2))*0.15;
  const cross = Math.sin(sx*0.12)*Math.sin(sy*0.12)+Math.sin((sx-sy)*0.08+t)*0.5;
  const voronoi = (() => {
    let md = 99, md2 = 99;
    for (let i=0;i<6;i++) {
      const vx = 80+i*72+Math.sin(t*0.3+i*1.1)*40;
      const vy = 40+Math.cos(t*0.25+i*0.9)*30+Math.sin(i*2.1)*60;
      const d = Math.sqrt((sx-vx)**2+(sy-vy)**2);
      if(d<md){md2=md;md=d}else if(d<md2){md2=d}
    }
    return Math.sin((md2-md)*0.4)*0.3;
  })();
  const reaction = Math.tanh((aS-iS*0.7+bg*0.3+spiral+cS*0.4+micro+voronoi)*2.0);
  const cell = Math.tanh((cross+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const pulse = Math.sin(t*0.8)*0.1;
  const blend = reaction*0.65+cell*0.2+voronoi*0.15+pulse;
  const v = blend*0.5+0.5;
  const hueShift = Math.sin(t*0.15)*0.08;
  const pal = [
    [5,12,52],[8,35,82],[12,62,100],[18,95,115],
    [28,130,130],[60,158,120],[120,172,95],
    [185,175,65],[210,150,55],[220,115,60],
    [200,80,65],[165,50,70],[120,30,60],[75,20,55],[35,15,52],[5,12,52]
  ];
  const idx = (v+hueShift)*(pal.length-1);
  const ai = Math.max(0,Math.min(idx|0,pal.length-2));
  const f = idx-ai;
  const lum = 0.82+Math.sin(reaction*Math.PI)*0.18;
  const edge = Math.abs(reaction)>0.65?1.18:Math.abs(reaction)>0.4?1.05:0.95;
  const glow = Math.max(0,reaction)*0.12;
  return [
    Math.min(255,((pal[ai][0]+(pal[ai+1][0]-pal[ai][0])*f)*lum*edge+glow*80)|0),
    Math.min(255,((pal[ai][1]+(pal[ai+1][1]-pal[ai][1])*f)*lum*edge+glow*60)|0),
    Math.min(255,((pal[ai][2]+(pal[ai+1][2]-pal[ai][2])*f)*lum*edge+glow*100)|0)
  ];
}
